/*
 * app.css --- Folha de estilo servida da camada web do LeadScorer.
 *
 * Consolida o chrome das duas aplicacoes (login e navbar) a partir dos
 * prototipos autonomos de '.claude/assets/examples/', servida como ativo
 * estatico sob '/assets/app.css' com CSP estrita (style-src 'self'). Os
 * tokens do design system (tema escuro IBM Carbon Gray 100) sao embutidos;
 * as fontes IBM Plex sao servidas de '/assets/fonts/'.
 *
 * A fonte canonica dos tokens reside em '.claude/assets/tokens/'; os valores
 * abaixo espelham o subconjunto do tema escuro utilizado.
 */

/* === Fontes IBM Plex (locais) === */
@font-face {
  font-family: 'IBM Plex Sans'; font-style: normal; font-weight: 400;
  font-display: swap; src: url('/assets/fonts/IBMPlexSans-Regular.woff2') format('woff2');
}
@font-face {
  font-family: 'IBM Plex Sans'; font-style: normal; font-weight: 500;
  font-display: swap; src: url('/assets/fonts/IBMPlexSans-Medium.woff2') format('woff2');
}
@font-face {
  font-family: 'IBM Plex Sans'; font-style: normal; font-weight: 600;
  font-display: swap; src: url('/assets/fonts/IBMPlexSans-SemiBold.woff2') format('woff2');
}
@font-face {
  font-family: 'IBM Plex Mono'; font-style: normal; font-weight: 400;
  font-display: swap; src: url('/assets/fonts/IBMPlexMono-Regular.woff2') format('woff2');
}
@font-face {
  font-family: 'IBM Plex Mono'; font-style: normal; font-weight: 500;
  font-display: swap; src: url('/assets/fonts/IBMPlexMono-Medium.woff2') format('woff2');
}
@font-face {
  font-family: 'IBM Plex Serif'; font-style: normal; font-weight: 600;
  font-display: swap; src: url('/assets/fonts/IBMPlexSerif-SemiBold.woff2') format('woff2');
}

/* === Tokens (embutidos do design system) === */
:root {
  --font-sans:  'IBM Plex Sans', system-ui, -apple-system, sans-serif;
  --font-serif: 'IBM Plex Serif', Georgia, serif;
  --font-mono:  'IBM Plex Mono', ui-monospace, Menlo, monospace;
  --bg-base: #161616; --bg-raised: #262626; --bg-overlay: #393939;
  --fg-primary: #f4f4f4; --fg-secondary: #c6c6c6; --fg-muted: #8d8d8d;
  --fg-disabled: #525252;
  --border-subtle: #262626; --border-strong: #393939;
  --accent: #ffffff; --accent-muted: rgba(255,255,255,0.08);
  --positive: #42be65; --negative: #fa4d56; --warning: #f1c21b; --info: #4589ff;
  --space-1: 4px; --space-2: 8px; --space-3: 12px; --space-4: 16px;
  --space-5: 24px; --space-6: 32px; --space-7: 48px; --space-8: 64px;
  --radius-sm: 2px; --radius-md: 4px;
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  background: var(--bg-base); color: var(--fg-primary);
  font-family: var(--font-sans); font-size: 14px; line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  min-height: 100vh; display: flex; flex-direction: column;
}
main { flex: 1; }

/* === Faixa superior minima (login: contexto de aplicacao) === */
.appbar {
  display: flex; align-items: baseline; gap: var(--space-3);
  padding: var(--space-4) var(--space-6);
  border-bottom: 1px solid var(--border-strong);
}
.wordmark {
  font-family: var(--font-serif); font-weight: 600; font-size: 20px;
  letter-spacing: -0.01em;
}
.appbar .scope {
  font-family: var(--font-mono); font-size: 12px; color: var(--fg-muted);
  text-transform: uppercase; letter-spacing: 0.08em;
}

/* === Barra de navegacao com menu responsivo (alternancia CSS pura) === */
.navbar {
  display: flex; align-items: center; gap: var(--space-6);
  padding: 0 calc(max(0px, (100% - 1360px) / 2) + var(--space-6));
  height: 56px; border-bottom: 1px solid var(--border-strong);
  position: sticky; top: 0; background: var(--bg-base); z-index: 20;
}
.navbar .brand { font-family: var(--font-serif); font-weight: 600; font-size: 18px; }
.navbar .brand .role {
  font-family: var(--font-mono); font-size: 11px; font-weight: 400;
  text-transform: uppercase; letter-spacing: 0.08em; color: var(--fg-muted);
  margin-left: var(--space-2);
}
.nav-cb { display: none; }
.nav-toggle {
  display: none; flex-direction: column; justify-content: center; gap: 4px;
  width: 24px; height: 24px; cursor: pointer;
}
.nav-toggle span { display: block; height: 1.5px; background: var(--fg-secondary); }
.nav-tabs {
  display: flex; gap: var(--space-5); flex: 1;
  margin-left: calc(100px - var(--space-6));
}
.nav-tabs a {
  color: var(--fg-muted); text-decoration: none; font-size: 14px;
  padding: 18px 0; border-bottom: 2px solid transparent; white-space: nowrap;
}
.nav-tabs a:hover { color: var(--fg-secondary); }
.nav-tabs a.active { color: var(--fg-primary); border-bottom-color: var(--accent); }
.nav-right { display: flex; align-items: center; gap: var(--space-4); }
.user-pill {
  font-family: var(--font-mono); font-size: 12px; color: var(--fg-secondary);
  text-decoration: none; border-bottom: 1px solid var(--border-strong);
}
.pill {
  display: inline-flex; align-items: center; gap: var(--space-2);
  font-family: var(--font-mono); font-size: 11px; text-transform: uppercase;
  letter-spacing: 0.06em; color: var(--fg-secondary);
  padding: 4px 10px; border: 1px solid var(--border-strong);
  border-radius: var(--radius-sm);
}
.dot { width: 7px; height: 7px; border-radius: 50%; background: var(--positive); }

/* === Botoes === */
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  padding: 6px 14px; font-family: var(--font-sans); font-size: 13px;
  font-weight: 500; border: 1px solid var(--border-strong);
  background: transparent; color: var(--fg-primary);
  border-radius: var(--radius-sm); cursor: pointer;
}
.btn:hover { background: var(--accent-muted); }
.btn-primary { background: var(--fg-primary); color: var(--bg-base); border-color: var(--fg-primary); }
.btn-primary:hover { background: var(--accent); }
.btn-sm { padding: 4px 12px; font-size: 12px; }
/* Modificador de largura total para o botao de submissao do login. */
.btn-block { width: 100%; padding: var(--space-3) var(--space-4); font-size: 14px; }
/* Botao de logout renderizado como formulario POST, sem quebrar a linha do navbar. */
.logout-form { display: inline; margin: 0; }

/* === Area central do login === */
.login-main {
  display: flex; align-items: center; justify-content: center;
  padding: var(--space-7) var(--space-4);
}
.card {
  width: 100%; max-width: 420px;
  background: var(--bg-raised); border: 1px solid var(--border-strong);
  border-radius: var(--radius-md); padding: var(--space-6);
}
.card h1 {
  font-family: var(--font-serif); font-weight: 600; font-size: 24px;
  margin: 0 0 var(--space-2);
}
.card .lead { color: var(--fg-secondary); margin: 0 0 var(--space-6); font-size: 14px; }
.field { margin-bottom: var(--space-5); }
.field > label {
  display: block; font-family: var(--font-mono); font-size: 11px;
  text-transform: uppercase; letter-spacing: 0.08em; color: var(--fg-muted);
  margin-bottom: var(--space-2);
}
.select { position: relative; display: block; }
.select select {
  -webkit-appearance: none; appearance: none;
  width: 100%; padding: var(--space-3) var(--space-4); padding-right: var(--space-8);
  background: var(--bg-base); color: var(--fg-primary);
  font-family: var(--font-sans); font-size: 14px;
  border: 1px solid var(--border-strong); border-radius: var(--radius-sm);
  cursor: pointer;
}
.select select:focus { outline: 2px solid var(--info); outline-offset: 0; }
.select::after {
  content: ''; position: absolute; right: var(--space-4); top: 50%;
  width: 8px; height: 8px; margin-top: -6px;
  border-right: 1px solid var(--fg-muted); border-bottom: 1px solid var(--fg-muted);
  transform: rotate(45deg); pointer-events: none;
}
.hint {
  margin-top: var(--space-5); padding-top: var(--space-4);
  border-top: 1px solid var(--border-subtle);
  font-size: 12px; color: var(--fg-muted);
}
.error {
  margin: 0 0 var(--space-5); padding: var(--space-3) var(--space-4);
  border: 1px solid var(--negative); border-radius: var(--radius-sm);
  color: var(--fg-primary); font-size: 13px;
}

/* === Layout de pagina (aplicacoes) === */
.page { padding: var(--space-6); max-width: 1360px; margin: 0 auto; width: 100%; }
.page-head {
  display: flex; align-items: baseline; gap: var(--space-3);
  margin-bottom: var(--space-5);
}
.page-head h1 { font-family: var(--font-serif); font-weight: 600; font-size: 22px; margin: 0; }
.page-head .sub { font-family: var(--font-mono); font-size: 12px; color: var(--fg-muted); }
.placeholder { color: var(--fg-secondary); font-size: 14px; max-width: 60ch; }

/* === Rodape === */
footer {
  padding: var(--space-4) var(--space-6);
  border-top: 1px solid var(--border-subtle);
  font-family: var(--font-mono); font-size: 11px; color: var(--fg-muted);
  letter-spacing: 0.04em;
}

/* === Indicador HTMX (htmx.config.includeIndicatorStyles em falso) === */
.htmx-indicator { opacity: 0; transition: opacity 0.12s; }
.htmx-request .htmx-indicator, .htmx-request.htmx-indicator { opacity: 1; }

/* === Responsivo (validacao no iPhone 13, 390 px) === */
@media (max-width: 820px) {
  .navbar { gap: var(--space-4); padding: 0 var(--space-4); }
  .nav-toggle { display: flex; }
  .nav-tabs {
    display: none; position: absolute; top: 56px; left: 0; right: 0;
    flex-direction: column; gap: 0; background: var(--bg-overlay);
    border-bottom: 1px solid var(--border-strong); z-index: 30; margin-left: 0;
  }
  .nav-tabs a { padding: 14px var(--space-4); border-bottom: 1px solid var(--border-subtle); }
  .nav-cb:checked ~ .nav-tabs { display: flex; }
}
@media (max-width: 560px) {
  .nav-right .user-pill { display: none; }
  .page { padding: var(--space-4); }
}

